package com.flymaccin.genericdaw; import android.app.Activity; import android.os.Bundle; import android.widget.*; public class StudioActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b); LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL); for(String s:new String[]{"ARRANGE","MIXER","PIANO ROLL","AUDIO"}){Button x=new Button(this);x.setText(s);p.addView(x);}setContentView(p);} }